const rightCache={};function rightRoute(p,q){const key=p+':'+q;if(Object.hasOwn(rightCache,key))return rightCache[key];const queue=[{at:'L'+p,paths:['RF'+p],req:{},visited:new Set(['L'+p])}];while(queue.length){const state=queue.shift();if(state.at==='E'+q)return rightCache[key]={paths:state.paths,req:state.req};for(const a of adj[state.at]||[]){if(state.visited.has(a.to)||nodes[a.to][0]<nodes[state.at][0]-.001)continue;const e=edges[a.id];if(Object.entries(e.req).some(([k,v])=>Object.hasOwn(state.req,k)&&state.req[k]!==v))continue;queue.push({at:a.to,paths:[...state.paths,a.id],req:{...state.req,...e.req},visited:new Set([...state.visited,a.to])});}}return rightCache[key]=null;}
