 if(gate==='H'){Object.assign(req,{'41':p===2?1:0,'42':p===1?1:0,'43':p===2?1:0});throat=['H'+p,'L_A'+p+'P','LF'+p];cross=true;}
 else if(end==='W'){if(gate==='AW'){req[p===1?'42':'43']=0;throat=['L_A'+p,'L_A'+p+'P','LF'+p];}else if(gate==='BW')throat=['L_B'+p,'LF'+p];else{const group=p<=6?'D':'U',normal=inbound?'D':'U';cross=group!==normal;req['15I']=cross&&inbound?1:0;req['15R']=cross&&!inbound?1:0;req[p<=6?'11':'12']=p===5||p===8?1:0;throat=['L_CS'+normal,cross?'L_CX'+(inbound?'I':'R'):'L_CN'+normal,'L_C'+group,'LC'+p,'LF'+p];}}
 else{const path=rightRoute(p,inbound?e.incoming:e.outgoing);Object.assign(req,path.req);cross=Object.entries(req).some(([k,v])=>v&&!['31','32'].includes(k));throat=inbound?path.paths.slice().reverse():path.paths.slice();}
